from src.editor_core.project import (    Asset,    Clip,    Project,    SubtitleCue,    SubtitleEffect,    SubtitleSpan,    Timeline,    Track,)def test_asset_from_dict_ignores_unknown_fields():    asset = Asset.from_dict(        {            "id": "asset-1",            "path": "/tmp/a.mp4",            "source": "local",            "media_type": "video",            "unexpected": "ignored",        }    )    assert asset.id == "asset-1"    assert not hasattr(asset, "unexpected")def test_timeline_from_dict_converts_nested_tracks_and_clips():    timeline = Timeline.from_dict(        {            "duration": 10.0,            "tracks": [                {                    "id": "track-1",                    "kind": "video",                    "clips": [                        {                            "id": "clip-1",                            "asset_id": "asset-1",                            "start": 0.0,                            "end": 4.0,                        }                    ],                }            ],        }    )    assert len(timeline.tracks) == 1    assert isinstance(timeline.tracks[0], Track)    assert isinstance(timeline.tracks[0].clips[0], Clip)def test_subtitle_cue_from_dict_converts_spans_and_effects():    cue = SubtitleCue.from_dict(        {            "id": "cue-1",            "start": 0.0,            "end": 1.0,            "text": "Hi",            "spans": [{"id": "span-1", "text": "Hi", "effects": [{"kind": "outline"}]}],            "effects": [{"kind": "fade_in", "parameters": {"duration": 0.2}}],        }    )    assert isinstance(cue.spans[0], SubtitleSpan)    assert isinstance(cue.spans[0].effects[0], SubtitleEffect)    assert isinstance(cue.effects[0], SubtitleEffect)def test_project_from_dict_builds_nested_types_and_lookup_helpers():    project = Project.from_dict(        {            "id": "project-1",            "name": "Demo",            "assets": [{"id": "asset-1", "path": "/tmp/a.mp4"}],            "timeline": {                "tracks": [                    {                        "id": "track-1",                        "kind": "video",                        "clips": [                            {                                "id": "clip-1",                                "asset_id": "asset-1",                                "start": 0.0,                                "end": 1.0,                            }                        ],                    }                ]            },        }    )    assert project.find_asset("asset-1") is not None    assert project.find_track("track-1") is not None    assert project.find_clip("clip-1") is not None    assert project.find_track_for_clip("clip-1").id == "track-1"    assert project.find_asset("missing") is Nonedef test_project_bump_version_increments_and_updates_timestamp():    project = Project(id="project-1", name="Demo")    initial_version = project.version    initial_updated_at = project.updated_at    project.bump_version()    assert project.version == initial_version + 1    assert project.updated_at != initial_updated_at